import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds 124.5 down (half to even)', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents rounds 125.5 up (half to even)', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds down 2.4', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents rounds -0.5 to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats positive amount', () => {
  const result = formatEuros(123456);
  assert.equal(result, '€1,234.56');
});

test('formatEuros formats negative amount', () => {
  const result = formatEuros(-5);
  assert.equal(result, '-€0.05');
});

test('formatEuros formats amount without thousands separator', () => {
  const result = formatEuros(999);
  assert.equal(result, '€9.99');
});

test('parseEuros parses simple number', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros parses decimal', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros parses with thousands separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros fails on invalid input', () => {
  const result = parseEuros('abc');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('RATES has EUR at 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES has USD at 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES has GBP at 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok for EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
});

test('convert EUR returns same amount', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.value, 100);
});

test('convert USD multiplies by rate', () => {
  const result = convert(100, 'USD');
  assert.equal(result.value, Math.round(100 * 1.085));
});

test('convert GBP multiplies by rate', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.value, Math.round(100 * 0.8425));
});

test('convert with unknown currency fails', () => {
  const result = convert(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with negative amount', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, Math.round(-100 * 1.085));
});

test('convert with zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert applies rounding', () => {
  const result = convert(333, 'USD');
  assert.ok(Number.isInteger(result.value));
});

test('formatMoney EUR uses euro symbol', () => {
  const result = formatMoney(12345, 'EUR');
  assert.ok(result.includes('€'));
});

test('formatMoney EUR formats correctly', () => {
  const result = formatMoney(12345, 'EUR');
  assert.equal(result, '€123.45');
});

test('formatMoney USD uses dollar symbol', () => {
  const result = formatMoney(12345, 'USD');
  assert.ok(result.includes('$'));
});

test('formatMoney USD formats correctly', () => {
  const result = formatMoney(12345, 'USD');
  assert.equal(result, '$123.45');
});

test('formatMoney GBP uses pound symbol', () => {
  const result = formatMoney(12345, 'GBP');
  assert.ok(result.includes('£'));
});

test('formatMoney GBP formats correctly', () => {
  const result = formatMoney(12345, 'GBP');
  assert.equal(result, '£123.45');
});

test('formatMoney with thousands separator', () => {
  const result = formatMoney(1234567, 'EUR');
  assert.equal(result, '€12,345.67');
});

test('formatMoney with negative amount', () => {
  const result = formatMoney(-12345, 'EUR');
  assert.equal(result, '-€123.45');
});

test('formatMoney with cents only', () => {
  const result = formatMoney(5, 'EUR');
  assert.equal(result, '€0.05');
});

test('formatMoney with zero', () => {
  const result = formatMoney(0, 'EUR');
  assert.equal(result, '€0.00');
});

test('formatMoney with large USD amount', () => {
  const result = formatMoney(9876543, 'USD');
  assert.equal(result, '$98,765.43');
});

test('formatMoney with large GBP amount', () => {
  const result = formatMoney(9876543, 'GBP');
  assert.equal(result, '£98,765.43');
});

test('convert then format gives consistent result', () => {
  const euroCents = 100;
  const usdResult = convert(euroCents, 'USD');
  const formatted = formatMoney(usdResult.value, 'USD');

  assert.ok(formatted.includes('$'));
